# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, Iterable, List, Tuple
from hourglass.models import Shift
from collections import defaultdict


def _tally(shifts: List[Shift]) -> Dict[str, List[int]]:
    tally = defaultdict(lambda: [0, 0])
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")
        tally[shift.worker][0] += 1
        tally[shift.worker][1] += shift.span.minutes
    return tally


def _by_hours(entry: Tuple[str, List[int]]) -> tuple:
    name, (_count, minutes) = entry
    return (-minutes, name)


def _ranked(tally: Dict[str, List[int]]) -> list:
    pairs = sorted(tally.items(), key=_by_hours)
    return [(name, *totals) for name, totals in pairs]


def _row(name: str, count: int, minutes: int) -> str:
    return f"{name}: {count} shifts, {minutes / 60:.1f} hours"


# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, most scheduled hours first."""
    items = list(shifts)
    if not items:
        raise ValueError("no shifts to total")
    tally = _tally(items)
    return [_row(*entry) for entry in _ranked(tally)]
