cat > tests/test_timesheet.py <<'EOF'
# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span


def make_shift(worker: str, start: int, end: int) -> Shift:
    return Shift(worker, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_worker_first(self):
        lines = timesheet_lines(
            [
                make_shift("Bea", 480, 540),
                make_shift("Ana", 480, 720),
                make_shift("Bea", 600, 660),
            ]
        )
        self.assertEqual(
            lines,
            [
                "Ana: 1 shifts, 4.0 hours",
                "Bea: 2 shifts, 2.0 hours",
            ],
        )

    def test_hours_use_one_decimal(self):
        lines = timesheet_lines([make_shift("Ana", 0, 100)])
        self.assertEqual(lines, ["Ana: 1 shifts, 1.7 hours"])

    def test_ties_break_by_name(self):
        lines = timesheet_lines(
            [make_shift("Zed", 0, 60), make_shift("Amy", 0, 60)]
        )
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([make_shift("  ", 0, 60)])


if __name__ == "__main__":
    unittest.main()
